    58	      value,
    59	    );
    60	  if (!parts) return false;
    61	  const [
    62	    ,
    63	    yearText,
    64	    monthText,
    65	    dayText,
    66	    hourText,
    67	    minuteText,
    68	    secondText,
    69	    ,
    70	    zoneHourText,
    71	    zoneMinuteText,
    72	  ] = parts;
    73	  const year = Number(yearText),
    74	    month = Number(monthText),
    75	    day = Number(dayText);
    76	  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
    77	  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
