   121	export function claudeUsageEvent(
   122	  rowValue: unknown,
   123	  session: string,
   124	): ObserveBatchEvent | null {
   125	  const row = object(rowValue),
   126	    message = object(row?.message),
   127	    usage = object(message?.usage);
