   129	    !id(session) ||
   130	    row?.type !== "assistant" ||
   131	    row.sessionId !== session ||
   132	    !id(message?.id) ||
   133	    !usage
   134	  )
   135	    return null;
   136	  const result = event(
   137	    "claude-code",
   138	    "claude.assistant_usage.v1",
   139	    session,
   140	    message.id,
   141	    row.timestamp,
   142	  );
