   224	  counter(attrs, "uncached_input_tokens", tokens.input);
   225	  counter(attrs, "cache_read_input_tokens", cache?.read);
   226	  counter(attrs, "cache_write_input_tokens", cache?.write);
   227	  counter(attrs, "reported_output_tokens", tokens.output);
   228	  counter(attrs, "reasoning_output_tokens", tokens.reasoning);
