   241	/** Read only the explicitly supplied regular file, retaining a bounded tail.
   242	 * No cursor: later Stop hooks can retry failed writes and delayed transcript flushes.
   243	 * Even a complete file scan cannot establish complete provider or subagent coverage.
   244	 */
   245	export function collectTranscriptUsage(
   246	  path: string,
   247	  host: "claude-code" | "codex",
   248	  session: string,
   249	  limits: { maxBytes?: number; maxEvents?: number } = {},
   250	): UsageCollection {
   251	  const result: UsageCollection = {
   252	    events: [],
   253	    status: "unavailable",
   254	    limited: false,
   255	    malformed: 0,
   256	  };
   257	  if (!isAbsolute(path) || !id(session)) return result;
   258	  const maxBytes = Math.min(
   259	    4 * 1024 * 1024,
   260	    Math.max(1, Math.floor(limits.maxBytes ?? 4 * 1024 * 1024)),
   261	  );
   262	  const maxEvents = Math.min(
   263	    1000,
   264	    Math.max(1, Math.floor(limits.maxEvents ?? 1000)),
   265	  );
   266	  let fd: number | undefined;
   267	  try {
   268	    if (!statSync(path).isFile()) return result;
   269	    fd = openSync(path, constants.O_RDONLY | (constants.O_NONBLOCK ?? 0));
   270	    const stat = fstatSync(fd);
   271	    if (!stat.isFile()) return result;
   272	    const start = Math.max(0, stat.size - maxBytes);
   273	    const buffer = Buffer.alloc(Math.min(stat.size, maxBytes));
   274	    const bytes = readSync(fd, buffer, 0, buffer.length, start);
   275	    let text = buffer.subarray(0, bytes).toString("utf8");
   276	    result.limited = start > 0 || bytes !== buffer.length;
   277	    if (start > 0) {
   278	      const previous = Buffer.alloc(1);
   279	      readSync(fd, previous, 0, 1, start - 1);
   280	      if (previous[0] !== 10) {
   281	        const boundary = text.indexOf("\n");
   282	        text = boundary < 0 ? "" : text.slice(boundary + 1);
   283	      }
   284	    }
   285	    const end = text.lastIndexOf("\n");
   286	    if (end !== text.length - 1) result.limited = true;
   287	    text = end < 0 ? "" : text.slice(0, end);
   288	    const lines = text.split("\n");
   289	    result.status = "partial";
   290	    for (let i = lines.length - 1; i >= 0; i--) {
   291	      if (!lines[i].trim()) continue;
   292	      try {
   293	        const row: unknown = JSON.parse(lines[i]);
   294	        const next =
   295	          host === "codex"
   296	            ? codexUsageEvent(row, session)
   297	            : claudeUsageEvent(row, session);
   298	        if (next) {
   299	          if (result.events.length === maxEvents) {
   300	            result.limited = true;
   301	            break;
   302	          }
   303	          result.events.push(next);
   304	        }
   305	      } catch {
   306	        result.malformed++;
   307	      }
   308	    }
   309	    result.events.reverse();
   310	  } catch {
   311	    /* Missing, unreadable or unsupported source stays unavailable. */
   312	  } finally {
   313	    if (fd !== undefined) closeSync(fd);
   314	  }
   315	  return result;
   316	}
   317	
   318	/** Acknowledged batch only: older CLI fallback cannot preserve source timestamps. */
   319	export function recordModelUsage(
   320	  binary: string,
   321	  cwd: string,
   322	  events: ObserveBatchEvent[],
   323	): boolean {
   324	  if (!events.length) return true;
   325	  try {
   326	    const output = execFileSync(binary, ["observe", "record", "--stdin"], {
   327	      cwd,
   328	      input: events.map((e) => JSON.stringify(e)).join("\n") + "\n",
   329	      timeout: 10000,
   330	      stdio: ["pipe", "pipe", "pipe"],
   331	    }).toString();
   332	    const ack = /^Recorded (\d+) event\(s\)(?:, skipped (\d+))?\s*$/i.exec(
   333	      output.trim(),
   334	    );
   335	    return (
   336	      ack !== null &&
   337	      Number(ack[1]) === events.length &&
   338	      Number(ack[2] ?? 0) === 0
   339	    );
   340	  } catch (error) {
   341	    debug(
   342	      "model-usage",
   343	      `Usage batch was not acknowledged: ${error instanceof Error ? error.name : "error"}`,
   344	    );
   345	    return false;
   346	  }
   347	}
   348	
   349	/** Keep repeated part broadcasts cheap; durable dedup/conflict handling is in Go. */
   350	export function createOpenCodeUsageRecorder(
   351	  write = recordModelUsage,
   352	): (binary: string, cwd: string, part: unknown) => void {
   353	  const acknowledged = new Set<string>();
   354	  return (binary, cwd, part) => {
   355	    const next = openCodeUsageEvent(part);
   356	    if (!next) return;
   357	    const fingerprint = JSON.stringify([cwd, next]);
   358	    if (acknowledged.has(fingerprint) || !write(binary, cwd, [next])) return;
   359	    acknowledged.add(fingerprint);
   360	    if (acknowledged.size > 1024)
   361	      acknowledged.delete(acknowledged.values().next().value!);
   362	  };
   363	}
