{"chunk_id":"569e74","wall_time_seconds":0.00000209,"exit_code":0,"original_token_count":1486,"output":"     1	#!/usr/bin/env node
     2	/**
     3	 * Session Summary Hook (Stop)
     4	 *
     5	 * Captures a session summary from the transcript when a session ends.
     6	 * Includes files modified, tools used, user tasks, and git commits.
     7	 *
     8	 * Storage:
     9	 * - Uses `aide memory add` with category=session
    10	 */
    11	
    12	import { debug, setDebugCwd } from "../lib/logger.js";
    13	import {
    14	  readStdin,
    15	  emitHookResult,
    16	  installHookSafetyNet,
    17	  findAideBinary,
    18	  detectPlatform,
    19	} from "../lib/hook-utils.js";
    20	import {
    21	  collectTranscriptUsage,
    22	  recordModelUsage,
    23	} from "../core/model-usage.js";
    24	import { setSessionContext } from "../lib/anchor.js";
    25	import {
    26	  buildSessionSummary,
    27	  getSessionCommits,
    28	  storeSessionSummary,
    29	} from "../core/session-summary-logic.js";
    30	import { getScopedState } from "../core/aide-client.js";
    31	import {
    32	  gatherPartials,
    33	  buildSummaryFromPartials,
    34	  cleanupPartials,
    35	} from "../core/partial-memory.js";
    36	
    37	const SOURCE = "session-summary";
    38	
    39	interface HookInput {
    40	  hook_event_name: string;
    41	  session_id: string;
    42	  cwd: string;
    43	  transcript_path?: string;
    44	  stop_hook_active?: boolean;
    45	}
    46	
    47	/**
    48	 * Generate and store a final session summary.
    49	 *
    50	 * Uses partials (if available) to enrich the transcript-based summary.
    51	 * After storing the final summary, cleans up all partials for this session
    52	 * by tagging them as "forget".
    53	 */
    54	function captureSessionSummary(
    55	  cwd: string,
    56	  sessionId: string,
    57	  transcriptPath: string,
    58	): boolean {
    59	  const binary = findAideBinary(cwd, sessionId);
    60	  if (!binary) {
    61	    debug(SOURCE, "aide binary not found, cannot capture session summary");
    62	    return false;
    63	  }
    64	
    65	  // Try to build the richest possible summary:
    66	  // 1. Gather partials from this session
    67	  // 2. Build from transcript (Claude Code has this)
    68	  // 3. Merge partials data with transcript summary
    69	  const partials = gatherPartials(binary, cwd, sessionId);
    70	  let summary: string | null = null;
    71	
    72	  if (partials.length > 0) {
    73	    // Build from partials + git data, scoped to this session's start time
    74	    // (session-scoped startedAt; falls back to "4 hours ago" inside
    75	    // getSessionCommits when the session never recorded one).
    76	    const startedAt = getScopedState(binary, cwd, sessionId, "startedAt");
    77	    const commits = getSessionCommits(cwd, startedAt ?? undefined);
    78	    summary = buildSummaryFromPartials(partials, commits, []);
    79	    debug(SOURCE, `Built summary from ${partials.length} partials`);
    80	  }
    81	
    82	  // Fall back to transcript-based summary if partials didn't produce enough
    83	  if (!summary) {
    84	    summary = buildSessionSummary(transcriptPath, cwd);
    85	  }
    86	
    87	  if (!summary) {
    88	    debug(SOURCE, "No summary generated (insufficient activity or transcript)");
    89	    // Still clean up partials even if no summary was generated
    90	    if (partials.length > 0) {
    91	      cleanupPartials(binary, cwd, sessionId);
    92	    }
    93	    return false;
    94	  }
    95	
    96	  const stored = storeSessionSummary(binary, cwd, sessionId, summary);
    97	  if (stored) {
    98	    debug(SOURCE, `Stored final session summary for ${sessionId.slice(0, 8)}`);
    99	    // Clean up partials now that the final summary is stored
   100	    const cleaned = cleanupPartials(binary, cwd, sessionId);
   101	    debug(SOURCE, `Cleaned up ${cleaned} partials after final summary`);
   102	  } else {
   103	    debug(SOURCE, "Failed to store session summary");
   104	  }
   105	  return stored;
   106	}
   107	
   108	async function main(): Promise<void> {
   109	  try {
   110	    const input = await readStdin();
   111	    if (!input.trim()) {
   112	      emitHookResult({ continue: true });
   113	      return;
   114	    }
   115	
   116	    const data: HookInput = JSON.parse(input);
   117	    const cwd = data.cwd || process.cwd();
   118	    const sessionId = data.session_id || "unknown";
   119	    setSessionContext(sessionId);
   120	
   121	    setDebugCwd(cwd);
   122	    debug(SOURCE, `Hook triggered: ${data.hook_event_name}`);
   123	
   124	    // For Stop hook, capture session summary
   125	    if (data.hook_event_name === "Stop" && data.transcript_path) {
   126	      // The transcript is an explicitly supplied source, not a discovery path.
   127	      // Stop can precede its flush; every scan remains partial coverage.
   128	      const binary = findAideBinary(cwd, sessionId);
   129	      if (binary) {
   130	        const usage = collectTranscriptUsage(
   131	          data.transcript_path,
   132	          detectPlatform(),
   133	          sessionId,
   134	        );
   135	        recordModelUsage(binary, cwd, usage.events);
   136	        debug(
   137	          SOURCE,
   138	          `Usage scan: ${usage.status}; limited=${usage.limited}; malformed=${usage.malformed}; records=${usage.events.length}`,
   139	        );
   140	      }
   141	      // Don't capture if stop hook is already active (avoid recursion)
   142	      if (!data.stop_hook_active) {
   143	        debug(SOURCE, "Stop hook - capturing session summary");
   144	        captureSessionSummary(cwd, sessionId, data.transcript_path);
   145	      }
   146	    }
   147	
   148	    emitHookResult({ continue: true });
   149	  } catch (err) {
   150	    debug(SOURCE, `Error: ${err}`);
   151	    emitHookResult({ continue: true });
   152	  }
