function createEventHandler(
  state: AideState,
): (input: { event: OpenCodeEvent }) => Promise<void> {
  const recordUsage = createOpenCodeUsageRecorder();
  return async ({ event }) => {
    switch (event.type) {
      case "session.created":
        establishContext(state, extractSessionId(event), "startup");
        await handleSessionCreated(state, event);
        break;
      case "session.compacted": {
        const session = extractSessionId(event);
        establishContext(state, session, "unknown");
        state.pruningTrackers.complete(session);
        if (state.binary)
          updateContextWindow(
            state.binary,
            state.cwd,
            { host: "opencode", sessionId: session, actorId: session },
            "compact",
          );
        break;
      }
      case "session.idle":
        await handleSessionIdle(state, event);
        break;
      case "session.deleted":
        await handleSessionDeleted(state, event);
        break;
      case "message.part.updated":
        if (state.binary)
          recordUsage(state.binary, state.cwd, event.properties.part);
        await handleMessagePartUpdated(state, event);
        break;
      default:
        // Ignore other events
        break;
    }
  };
}

